sys_script_fix.script:
(function executePostInstall() {
    var tableName = 'change_request';
    var fieldName = 'category';
    gs.log("Cisco Secure Access post-install script starting...");

    // 1. Add Category choice (if not exists)
    var choiceGR = new GlideRecord('sys_choice');
    choiceGR.addQuery('name', tableName);
    choiceGR.addQuery('element', fieldName);
    choiceGR.addQuery('value', 'CSA Configuration');
    choiceGR.query();
    if (!choiceGR.next()) {
        choiceGR.initialize();
        choiceGR.sys_scope = 'global';         // ensure record is global-scope
        choiceGR.name = tableName;
        choiceGR.element = fieldName;
        choiceGR.value = 'CSA Configuration';
        choiceGR.label = 'Cisco Secure Access';
        choiceGR.sequence = 400;
        choiceGR.inactive = false;
        choiceGR.language = 'en';
        choiceGR.insert();
        gs.log("Post-Install: Added category choice 'Cisco Secure Access'");
    }

    // 2. Create text field u_destination_address (if not exists)
    var dictText = new GlideRecord('sys_dictionary');
    dictText.addQuery('name', tableName);
    dictText.addQuery('element', 'u_destination_address');
    dictText.query();
    if (!dictText.next()) {
        dictText.initialize();
        dictText.sys_scope = 'global';
        dictText.name = tableName;
        dictText.element = 'u_destination_address';
        dictText.internal_type = 'string';
        dictText.column_label = 'Destination Address';
        dictText.max_length = 255;
        dictText.mandatory = false;
        dictText.insert();
        gs.log("Post-Install: Created field u_destination_address");
    }

    // 3. Create reference field u_destination_list (if not exists)
    var dictRef = new GlideRecord('sys_dictionary');
    dictRef.addQuery('name', tableName);
    dictRef.addQuery('element', 'u_destination_list');
    dictRef.query();
    if (!dictRef.next()) {
        dictRef.initialize();
        dictRef.sys_scope = 'global';
        dictRef.name = tableName;
        dictRef.element = 'u_destination_list';
        dictRef.internal_type = 'reference';
        dictRef.reference = 'u_cisco_secure_access_destination_list'; // your reference table
        dictRef.column_label = 'Destination List';
        dictRef.mandatory = false;
        dictRef.insert();
        gs.log("Post-Install: Created field u_destination_list");
    }

    // 4. Create UI Policy on change_request (if not exists)
    var policyGR = new GlideRecord('sys_ui_policy');
    policyGR.addQuery('short_description', 'Show Cisco secure access fields');
    policyGR.addQuery('table', tableName);
    policyGR.query();
    var policyId;
    if (!policyGR.next()) {
        policyGR.initialize();
        policyGR.sys_scope = 'global';
        policyGR.short_description = 'Show Cisco secure access fields';
        policyGR.table = tableName;
        policyGR.active = true;
        policyGR.reverse_if_false = true;
        policyGR.on_load = true;
        policyGR.conditions = 'category=CSA Configuration';
        policyId = policyGR.insert();
        gs.log("Post-Install: Created UI Policy 'Show Cisco secure access fields'");
    } else {
        policyId = policyGR.getValue('sys_id');
        gs.log("UI Policy already exists (ID: " + policyId + ")");
    }

    // 5. Create UI Policy Action for u_destination_address
    var actionGR1 = new GlideRecord('sys_ui_policy_action');
    actionGR1.addQuery('ui_policy', policyId);
    actionGR1.addQuery('field', 'u_destination_address');
    actionGR1.query();
    if (!actionGR1.next()) {
        actionGR1.initialize();
        actionGR1.sys_scope = 'global';
        actionGR1.ui_policy = policyId;
        actionGR1.field = 'u_destination_address';
        actionGR1.visible = true;
        actionGR1.mandatory = true;
        actionGR1.disabled = false;
        actionGR1.insert();
        gs.log("Post-Install: Created UI Policy action for u_destination_address");
    }

    // 6. Create UI Policy Action for u_destination_list
    var actionGR2 = new GlideRecord('sys_ui_policy_action');
    actionGR2.addQuery('ui_policy', policyId);
    actionGR2.addQuery('field', 'u_destination_list');
    actionGR2.query();
    if (!actionGR2.next()) {
        actionGR2.initialize();
        actionGR2.sys_scope = 'global';
        actionGR2.ui_policy = policyId;
        actionGR2.field = 'u_destination_list';
        actionGR2.visible = true;
        actionGR2.mandatory = true;
        actionGR2.disabled = false;
        actionGR2.insert();
        gs.log("Post-Install: Created UI Policy action for u_destination_list");
    }

    gs.log("Cisco Secure Access post-install script completed.");
})();
